"""Shared CLI and Markdown formatting helpers for `scripts/docs/` generators."""

from __future__ import annotations

import argparse
import difflib
import pathlib
import sys
from collections.abc import Callable

from flexmesa.testing import _dashboard_render

DEFAULT_REPO_ROOT = pathlib.Path(__file__).resolve().parents[2]
REPO_URL = _dashboard_render.REPO_URL
GH_BLOB = f"{REPO_URL}/blob/main"


def generated_comment(script_relpath: str, issues: str) -> str:
    """Return the standard auto-generated banner comment for docs pages."""
    return (
        f"<!-- GENERATED BY `{script_relpath}` ({issues}). "
        "DO NOT EDIT BY HAND. -->"
    )


def issue_sort_key(issue: str) -> tuple[int, str]:
    """Sort `#N` GitHub issue references numerically."""
    digits = issue.lstrip("#")
    return (int(digits) if digits.isdigit() else 999999, issue)


def issue_link(issue: str) -> str:
    """Format `#N` as a Markdown link to the repository issue tracker."""
    clean = issue.lstrip("#")
    if clean.isdigit():
        return _dashboard_render._issue_link(clean)
    return f"[{issue}]({REPO_URL}/issues/{clean})"


def run_render_cli(
    *,
    argv: list[str] | None,
    description: str,
    default_rel_output: pathlib.Path,
    render_fn: Callable[[pathlib.Path], str],
    regen_cmd: str,
    check_ok_msg: str,
) -> int:
    """Run the shared `--repo-root` / `--output` / `--check` generator CLI.

    Args:
        argv: Optional argument list overriding `sys.argv[1:]`.
        description: Argument parser description string.
        default_rel_output: Repository-relative Markdown target path.
        render_fn: Callable rendering expected Markdown from `repo_root`.
        regen_cmd: Command printed on drift during `--check`.
        check_ok_msg: Template string formatted with `out_path` when fresh.

    Returns:
        Exit status code (`0` on success, `1` on `--check` drift or missing).
    """
    parser = argparse.ArgumentParser(description=description)
    parser.add_argument(
        "--repo-root",
        type=pathlib.Path,
        default=DEFAULT_REPO_ROOT,
        help="Path to FlexMESA repository root.",
    )
    parser.add_argument(
        "--output",
        type=pathlib.Path,
        default=None,
        help="Optional Markdown output path.",
    )
    parser.add_argument(
        "--check",
        action="store_true",
        help="Verify target matches deterministic output without writing.",
    )
    args = parser.parse_args(argv)

    repo_root = args.repo_root.resolve()
    out_path = (
        args.output.resolve()
        if args.output is not None
        else repo_root / default_rel_output
    )
    expected = render_fn(repo_root)

    if args.check:
        if not out_path.is_file():
            sys.stderr.write(f"Missing generated file: {out_path}\n")
            return 1
        actual = out_path.read_text(encoding="utf-8")
        if actual != expected:
            diff = "".join(
                difflib.unified_diff(
                    actual.splitlines(keepends=True),
                    expected.splitlines(keepends=True),
                    fromfile=str(out_path),
                    tofile="expected",
                )
            )
            sys.stderr.write(
                f"{default_rel_output.as_posix()} is out of date. Run "
                f"`{regen_cmd}`.\n{diff[:2000]}\n"
            )
            return 1
        print(check_ok_msg.format(out_path=out_path))
        return 0

    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(expected, encoding="utf-8")
    print(f"Wrote {out_path}")
    return 0
